PostgreSQL, one transaction, safe to run any number of times:

```sql
-- migrate_split_full_name.sql
BEGIN;

ALTER TABLE users ADD COLUMN IF NOT EXISTS first_name text;
ALTER TABLE users ADD COLUMN IF NOT EXISTS last_name  text;

-- Backfill only rows not yet migrated, and only if full_name still exists
-- (so re-running after the later drop step is a no-op, not an error).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = 'users' AND column_name = 'full_name') THEN
    UPDATE users
    SET first_name = split_part(n, ' ', 1),
        last_name  = NULLIF(substr(n, length(split_part(n, ' ', 1)) + 2), '')
    FROM (SELECT id, regexp_replace(btrim(full_name), '\s+', ' ', 'g') AS n
          FROM users) s
    WHERE users.id = s.id
      AND users.first_name IS NULL
      AND s.n <> '';
    -- ponytail: "first token / everything else" split. Wrong for
    -- "Ludwig van Beethoven"-style surnames and mononyms by design; fix those by hand.
  END IF;
END $$;

COMMIT;
```

Self-check (run against a scratch DB):

```sql
BEGIN;
CREATE TEMP TABLE users (id serial PRIMARY KEY, full_name text);
INSERT INTO users (full_name) VALUES
  ('Ada Lovelace'), ('  Grace   Brewster  Hopper '), ('Cher'), (''), (NULL);
\i migrate_split_full_name.sql
\i migrate_split_full_name.sql   -- second run must change nothing
DO $$ BEGIN
  ASSERT (SELECT first_name||'|'||last_name FROM users WHERE id=1) = 'Ada|Lovelace';
  ASSERT (SELECT first_name||'|'||last_name FROM users WHERE id=2) = 'Grace|Brewster Hopper';
  ASSERT (SELECT first_name FROM users WHERE id=3) = 'Cher'
     AND (SELECT last_name FROM users WHERE id=3) IS NULL;
  ASSERT (SELECT count(*) FROM users WHERE id IN (4,5) AND first_name IS NOT NULL) = 0;
END $$;
ROLLBACK;
```
(Remove the `BEGIN/COMMIT` in the migration when nesting via `\i`, or just run the asserts after it.)

Skipped: dropping `full_name` — do it in a separate migration once the app writes the new columns (`ALTER TABLE users DROP COLUMN IF EXISTS full_name;`). Skipped: batched backfill — single `UPDATE` locks every row; batch by `id` ranges if the table is in the millions and can't take that lock.
